Definition sc_fin_W (px ff fp : Z) : list (Z * Z) :=
  [(px + 128, px + 136); (ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16); (fp, fp + 1)]%Z.

Definition sc_fin_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (px out k lo shi ff fp : Z) (bg inn en mxw : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (sc_fin_W px ff fp) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' (px + 112) [C8 bg; C8 inn; C8 (Z_to_bv 64 (out + k)); C8 (Z_to_bv 64 (out + k)); C8 en; C8 mxw]
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.
